mapper.select:
SELECT 1
FROM ${tableName}
WHERE status_cd = '0'
  AND `name` = #{name}
  AND department = #{department}

      AND start_time <= #{attendanceDate}
      AND end_time >= #{attendanceDate}


      AND start_time <= #{fixedStartWorkDateTime}


      AND end_time >= #{fixedEndWorkDateTime}

LIMIT 1

SELECT start_time startTime, end_time endTime
FROM ${tableName}
WHERE status_cd = '0'
  AND `name` = #{name}
  AND department = #{department}
  AND (DATE_FORMAT(start_time,'%Y-%m-%d') = #{attendanceDate} OR DATE_FORMAT(end_time,'%Y-%m-%d') = #{attendanceDate})

SELECT start_time startTime, end_time endTime
FROM ${tableName}
WHERE status_cd = '0'
  AND `name` = #{name}
  AND department = #{department}
  AND (DATE_FORMAT(start_time,'%Y-%m-%d') <= #{attendanceDate} AND DATE_FORMAT(end_time,'%Y-%m-%d') >= #{attendanceDate})

SELECT f.id, f.file_name fileName, DATE_FORMAT(f.file_time, '%Y年%c月') fileTime, f.data_type dataType, f.import_time importTime, u.name uploader
FROM attendance_file f
LEFT JOIN u_user u ON u.user_id = f.user_id AND u.status_cd = '0'
WHERE f.status_cd = '0'

    AND f.file_name LIKE concat('%', #{fileName}, '%')


    AND f.file_time = #{fileTime}


    AND f.data_type = #{dataType}


    AND u.name LIKE concat('%', #{name}, '%')

ORDER BY f.create_time DESC

    limit #{page}, #{row}

SELECT COUNT(DISTINCT f.id) count FROM attendance_file f LEFT JOIN u_user u ON u.user_id = f.user_id AND u.status_cd = '0' WHERE f.status_cd = '0'
AND f.file_name LIKE concat('%', #{fileName}, '%')
AND f.file_time = #{fileTime}
AND f.data_type = #{dataType}
AND u.name LIKE concat('%', #{uploader}, '%')
